import type { BankQuestion } from "@/lib/bank";

/** Verbal Ability for Placements (Placement Aptitude): 139 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "apt-verbal-placement-1", "question": "Choose the word closest in meaning to the word in capitals as used in the sentence.\nThe auditor was METICULOUS in checking every invoice.", "options": ["Thorough", "Careless", "Generous", "Hasty"], "answer": 0, "explanation": "Meticulous means showing great attention to detail, i.e. thorough. Careless and hasty are its opposites.", "difficulty": "easy", "source": "Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-2","question":"Choose the word opposite in meaning to the word in capitals as used in the sentence.\nThe company promised a TRANSPARENT hiring process.","options":["Clear","Opaque","Open","Fair"],"answer":1,"explanation":"Transparent here means open and easy to see into; the opposite is opaque (hidden, unclear). Clear and open are synonyms.","difficulty":"easy","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-3","question":"Fill in the blank.\nShe has been working with the analytics team ___ 2019.","options":["from","for","since","by"],"answer":2,"explanation":"With the present perfect continuous, 'since' marks a point in time (2019) and 'for' marks a length of time (for six years).","difficulty":"easy","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-5","question":"Fill in the blank with the correct preposition.\nRahul is good ___ solving puzzles, so he enjoys the reasoning round.","options":["at","in","on","with"],"answer":0,"explanation":"The fixed expression is 'good at' something. 'Good in' is a common error; 'good with' is used for people or tools (good with children, good with numbers).","difficulty":"easy","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-6","question":"Choose the one word for: a person who is new to a job or activity and has little experience.","options":["Veteran","Novice","Expert","Mentor"],"answer":1,"explanation":"A novice is a beginner. A veteran has long experience and a mentor guides others.","difficulty":"easy","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-7","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nEach of the interns / have been given / a separate laptop for the project. / No error","options":["Each of the interns","a separate laptop for the project","have been given","No error"],"answer":2,"explanation":"'Each of' takes a singular verb: 'Each of the interns has been given'. The plural noun 'interns' just before the verb is the trap.","difficulty":"moderate","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-8","question":"Fill in the blank.\nDespite repeated reminders, the vendor failed to ___ with the terms of the contract.","options":["obey","respect","follow","comply"],"answer":3,"explanation":"'Comply with' is the correct collocation. Obey, follow and respect take a direct object without 'with' (obey the terms, follow the terms).","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-9","question":"Choose the meaning of the idiom in capitals.\nWith revenue falling, the new manager decided to BITE THE BULLET and close two loss-making branches.","options":["Face a painful situation with courage","Make a hasty, careless decision","Put off a difficult choice","Blame someone else for a problem"],"answer":0,"explanation":"To bite the bullet is to accept something unpleasant but necessary and get on with it. 'Put off a difficult choice' is the opposite.","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-10","question":"Choose the word that best replaces the phrasal verb in capitals.\nThe product launch was CALLED OFF because of the budget cuts.","options":["Postponed","Cancelled","Announced","Approved"],"answer":1,"explanation":"To call off is to cancel. Postponed would be 'put off', the usual confusion.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-11","question":"Choose the correct passive form of: \"The committee will announce the results tomorrow.\"","options":["The results would be announced by the committee tomorrow.","The results will announce by the committee tomorrow.","The results will be announced by the committee tomorrow.","The results are announced by the committee tomorrow."],"answer":2,"explanation":"Future simple active (will announce) becomes 'will be + past participle' in the passive. The tense must not change to 'would' or 'are'.","difficulty":"easy","source":"TCS NQT verbal pattern"},
  {"id":"apt-verbal-placement-12","question":"Choose the correct indirect form of: He said, \"I met the recruiter yesterday.\"","options":["He said that I had met the recruiter the day before.","He said that he has met the recruiter the previous day.","He said that he met the recruiter yesterday.","He said that he had met the recruiter the previous day."],"answer":3,"explanation":"With a past reporting verb, simple past (met) shifts to past perfect (had met), 'yesterday' becomes 'the previous day' and 'I' becomes 'he'.","difficulty":"easy","source":"TCS NQT verbal pattern"},
  {"id":"apt-verbal-placement-13","question":"Fill in the blank.\nThe new leave policy will ___ all permanent employees from next month.","options":["affect","infect","effect","afflict"],"answer":0,"explanation":"'Affect' is the verb meaning to have an influence on. 'Effect' as a verb means to bring about (effect a change), and 'afflict' means to cause suffering.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-14","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: As a result, many new hires spend their first week waiting for access.\nQ: Most companies issue laptops and system logins only after the joining formalities are complete.\nR: A few firms have fixed this by setting up accounts a week before the joining date.\nS: These formalities can take several days.","options":["SQPR","QSPR","QPSR","RQSP"],"answer":1,"explanation":"Q introduces the practice, S ('These formalities') follows from Q, P gives the result of that delay, and R ('fixed this') offers the solution. QPSR breaks the 'These formalities' link.","difficulty":"moderate","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-15","question":"Choose the correct option to fill the blank.\nIf I ___ the team lead, I would change the release schedule.","options":["was","had","were","am"],"answer":2,"explanation":"An unreal present condition takes the subjunctive 'were' for all persons: 'If I were…, I would…'.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-16","question":"You missed a report deadline for a client. Which is the most appropriate opening line for your formal email?","options":["Please note that the delay was not our fault.","As you may know, deadlines are sometimes unrealistic.","Hey, sorry the report's late!","We sincerely apologise for the delay in delivering the report, which was due on 3 March."],"answer":3,"explanation":"A formal client email opens by owning the problem politely and specifically. The others are too casual or defensive.","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-17","question":"Choose the word closest in meaning to the word in capitals.\nThe CEO was CANDID about the quarter's losses at the town hall.","options":["Frank","Vague","Cautious","Cheerful"],"answer":0,"explanation":"Candid means open and honest, i.e. frank. Cautious and vague suggest holding back, which is the opposite.","difficulty":"moderate","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-18","question":"Choose the word opposite in meaning to the word in capitals.\nThe first draft of the proposal was VERBOSE, so the manager asked for a one-page version.","options":["Detailed","Concise","Lengthy","Wordy"],"answer":1,"explanation":"Verbose means using more words than needed; its opposite is concise. Wordy and lengthy are synonyms; the context (one-page version) confirms it.","difficulty":"moderate","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id": "apt-verbal-placement-19", "question": "Fill in the blank.\nNeither the manager nor the employees ___ aware of the change in policy.", "options": ["has been", "was", "were", "is"], "answer": 2, "explanation": "With 'neither … nor', the verb agrees with the nearer subject. 'Employees' is plural, so 'were'.", "difficulty": "moderate", "source": "Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-20","question":"Read the passage and answer the question.\n\nPassage: For decades, manufacturers prized lean inventories: every part arrived just before it was needed, and warehouses shrank. The approach cut storage costs, but it left little room for error. When a single supplier halted production, entire assembly lines stood idle within days. Many firms now keep a modest buffer of critical components, accepting higher holding costs as the price of resilience. Critics argue this merely shifts risk to the balance sheet; supporters reply that an idle factory costs far more than a full warehouse.\n\nWhich of the following best states the main idea of the passage?","options":["Warehouses are more profitable than factories.","Lean inventories have no real advantages.","Suppliers often halt production deliberately.","Many firms are giving up some cost efficiency in exchange for protection against supply disruptions."],"answer":3,"explanation":"The passage describes the shift from pure lean inventory to keeping buffers, accepting higher costs for resilience. It grants that lean cut storage costs, so 'no advantages' is wrong.","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-21","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe number of applicants / for the trainee post / have increased this year. / No error","options":["have increased this year","for the trainee post","The number of applicants","No error"],"answer":0,"explanation":"'The number of' is singular (it refers to one number): 'has increased'. Compare 'A number of applicants have applied', where the meaning is plural.","difficulty":"moderate","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id": "apt-verbal-placement-22", "question": "Find the part of the sentence that has an error. If there is none, choose \"No error\".\nHardly had the presentation begun / than the projector / stopped working. / No error", "options": ["Hardly had the presentation begun", "than the projector", "stopped working", "No error"], "answer": 1, "explanation": "'Hardly' and 'scarcely' pair with 'when' (or 'before'), not 'than'. Only 'no sooner' takes 'than'.", "difficulty": "moderate", "source": "Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-23","question":"Choose the pair of words that best fills the blanks.\nThe proposal was ___ by the board because it was financially ___.","options":["shelved … viable","rejected … sound","rejected … unviable","approved … unviable"],"answer":2,"explanation":"'Because' needs a reason that fits the action: a proposal is rejected because it is unviable. The other pairs set up a contradiction.","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-24","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nThe first and last sentences are fixed.\n1. The company's first product was a simple invoicing tool for small shops.\nP: Encouraged, the founders added payroll and tax filing.\nQ: Within two years, it had more than ten thousand paying users.\nR: The bundle, however, proved too complex for the shops it was built for.\nS: Many customers cancelled and went back to the basic tool sold by a rival.\n6. The founders eventually split the product back into separate, simpler apps.","options":["QPSR","PQRS","QRPS","QPRS"],"answer":3,"explanation":"Q (success) explains 'Encouraged' in P; P adds features, which R calls 'the bundle'; S gives the consequence, which leads to the fix in sentence 6.","difficulty":"hard","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id": "apt-verbal-placement-25", "question": "Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: This is because a written record lets everyone return to what was agreed.\nQ: Teams that work across time zones often rely on written updates rather than calls.\nR: Without such a record, the same question tends to be answered again and again, which is why many teams make the written update compulsory.\nS: It also lets a colleague who was asleep during the discussion catch up the next morning.", "options": ["QPSR", "QSPR", "QPRS", "PQSR"], "answer": 0, "explanation": "Q states the practice, P gives the first reason ('This is because'), S adds a second benefit ('It also'), and R closes with what happens without the record and the resulting rule.", "difficulty": "hard", "source": "Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-26","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: He listed the exact steps that had failed and the fix the team had applied.\nQ: After the outage, the engineering head sent a short note to all clients.\nR: He ended by naming a date by which a permanent solution would be in place.\nS: He began with an apology, without excuses.","options":["QSRP","QSPR","QPSR","SQPR"],"answer":1,"explanation":"Q introduces the note. 'Began' (S), the details (P) and 'ended' (R) mark the order of its contents.","difficulty":"hard","source":"TCS NQT verbal pattern"},
  {"id": "apt-verbal-placement-27", "question": "Read the passage and answer the question.\n\nPassage: When the firm moved half its support staff to remote work, managers expected productivity to fall. Instead, ticket resolution times improved by about a tenth within six months. Exit interviews, however, told a different story: newer employees reported feeling isolated and said they had learned the job more slowly without colleagues nearby. The company has since asked recent hires to spend three days a week in the office, while experienced staff may continue to work from home.\n\nWhich of the following can be inferred from the passage?", "options": ["The company plans to bring every employee back to the office.", "Exit interviews showed that all remote employees felt isolated.", "The company believes that working near colleagues helps new employees learn the job.", "Remote work lowered the productivity of experienced staff."], "answer": 2, "explanation": "Asking only recent hires to come in, after they reported learning more slowly alone, shows the company links in-person contact with learning. Productivity rose, so the second option contradicts the passage; the third overgeneralises from 'newer employees'.", "difficulty": "hard", "source": "Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-28","question":"Read the passage and answer the question.\n\nPassage: For decades, manufacturers prized lean inventories: every part arrived just before it was needed, and warehouses shrank. The approach cut storage costs, but it left little room for error. When a single supplier halted production, entire assembly lines stood idle within days. Many firms now keep a modest buffer of critical components, accepting higher holding costs as the price of resilience. Critics argue this merely shifts risk to the balance sheet; supporters reply that an idle factory costs far more than a full warehouse.\n\nAs used in the passage, the word 'resilience' most nearly means:","options":["The ability to lower holding costs","The speed at which parts are delivered","The ability to keep operating through disruptions","A refusal to change suppliers"],"answer":2,"explanation":"Firms accept higher holding costs as the price of resilience, i.e. of not having lines stand idle when a supplier fails. Lower holding costs is the thing they give up.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-29","question":"Read the passage and answer the question.\n\nPassage: For decades, manufacturers prized lean inventories: every part arrived just before it was needed, and warehouses shrank. The approach cut storage costs, but it left little room for error. When a single supplier halted production, entire assembly lines stood idle within days. Many firms now keep a modest buffer of critical components, accepting higher holding costs as the price of resilience. Critics argue this merely shifts risk to the balance sheet; supporters reply that an idle factory costs far more than a full warehouse.\n\nThe tone of the passage is best described as:","options":["Sharply critical of lean methods","Enthusiastic about large warehouses","Dismissive of the critics","Balanced and explanatory"],"answer":3,"explanation":"The author explains the benefit of lean inventories, their weakness, the response, and both the critics' and supporters' views without taking sides.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-30","question":"Read the passage and answer the question.\n\nPassage: A mid-sized software company banned internal meetings on Wednesdays. The rule was meant to give engineers long stretches of uninterrupted time. After a quarter, the number of code changes shipped on Wednesdays rose sharply, but so did the volume of internal chat messages, as staff tried to settle by text what they would once have settled in a ten-minute call. Some team leads now argue that the policy did not remove coordination costs; it only moved them.\n\nWhich of the following is the most suitable title for the passage?","options":["Meeting-free Wednesdays: Time Gained, Coordination Moved","The End of Office Meetings","Why Chat Tools Should Be Banned","How Engineers Ship Code"],"answer":0,"explanation":"The passage reports more shipped code (time gained) and more chat (coordination moved). The other titles are too broad or argue something the passage does not.","difficulty":"hard","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-31","question":"Choose the meaning of the idiom in capitals.\nThe contractor CUT CORNERS on the new office, and the roof began leaking within a month.","options":["Negotiated a lower price","Did the work cheaply by ignoring proper standards","Finished the work ahead of schedule","Reduced the size of the building"],"answer":1,"explanation":"To cut corners is to save time or money by skipping what should be done properly; the leaking roof confirms the negative sense.","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-32","question":"Choose the correct replacement for the part in capitals.\nNot only the interns but also the manager WERE LATE for the review.","options":["have been late","were late (no change)","was late","are late"],"answer":2,"explanation":"With 'not only … but also', the verb agrees with the nearer subject, 'the manager' (singular): 'was late'.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-33","question":"In which sentence is the word 'principal' or 'principle' used correctly?","options":["She refused to sign, as a matter of principal.","Our company's guiding principals are honesty and speed.","The principle reason for the delay was a shortage of staff.","The loan's principal will be repaid over five years."],"answer":3,"explanation":"Principal = main, or the capital sum of a loan; principle = a rule or belief. So 'principal reason', 'matter of principle' and 'guiding principles' are the correct forms.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-34","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe committee has submitted / its final report / to the board of directors. / No error","options":["No error","its final report","to the board of directors","The committee has submitted"],"answer":0,"explanation":"The committee acts as one body here, so the singular 'has' and 'its' are correct and consistent. Changing to 'have … their' would only be needed if members acted separately.","difficulty":"moderate","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-35","question":"Fill in the blank.\nThe new billing software is ___ the old one in every respect.","options":["more superior than","superior to","superior than","more superior to"],"answer":1,"explanation":"Latin comparatives such as superior, inferior, senior and junior take 'to', not 'than', and never 'more' (they are already comparative).","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id": "apt-verbal-placement-36", "question": "Choose the meaning of the word in capitals as used in the sentence.\nThe board will ADDRESS the shareholders' concerns at the annual meeting.", "options": ["Find the location of", "Deliver a speech to", "Deal with", "Write a letter to"], "answer": 2, "explanation": "To address a concern or problem is to deal with it. 'Address' meaning to speak to applies to people (address the shareholders), not to concerns.", "difficulty": "moderate", "source": "Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-37","question":"Choose the correct replacement for the part in capitals.\nThe team lead, along with her colleagues, ARE ATTENDING the summit in Pune.","options":["were attending","are attending (no change)","have been attending","is attending"],"answer":3,"explanation":"Phrases like 'along with', 'as well as' and 'together with' do not make the subject plural. The subject is 'the team lead': 'is attending'.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-38","question":"Choose the best rewrite of: \"Walking into the office, the printer was making a strange noise.\"","options":["As I walked into the office, I heard the printer making a strange noise.","The printer, walking into the office, was making a strange noise.","Walking into the office, a strange noise was made by the printer.","Walking into the office, the printer's strange noise was heard."],"answer":0,"explanation":"The original has a dangling modifier: it says the printer was walking. Only the first rewrite gives 'walking' a real person as its doer.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-39","question":"Choose the option that makes the sentence grammatically parallel.\nThe role requires analysing data, to prepare reports and the presentation of findings to clients.","options":["the analysis of data, to prepare reports and presenting findings to clients","analysing data, preparing reports and presenting findings to clients","analysing data, to prepare reports and presenting findings to clients","to analyse data, preparing reports and the presentation of findings to clients"],"answer":1,"explanation":"Items in a list should share one form. Three -ing forms (analysing, preparing, presenting) are parallel; the others mix -ing, infinitive and noun forms.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-40","question":"Which is the most suitable rewrite of \"We'll get back to you ASAP\" for a formal letter to a client?","options":["We will get back to you real quick.","We shall revert at the earliest, no worries.","We will respond to your query as soon as possible.","Will get back ASAP, thanks!"],"answer":2,"explanation":"Formal register avoids contractions, abbreviations like ASAP and casual phrases like 'no worries' or 'real quick'.","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id": "apt-verbal-placement-41", "question": "Choose the word opposite in meaning to the word in capitals.\nAfter three rounds, the salary negotiations reached an IMPASSE.", "options": ["Standstill", "Stalemate", "Deadlock", "Breakthrough"], "answer": 3, "explanation": "An impasse is a situation in which no progress is possible. Deadlock, stalemate and standstill are synonyms; a breakthrough is its opposite.", "difficulty": "moderate", "source": "Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-42","question":"Fill in the blank.\nThe audit revealed several ___ between the invoices raised and the payments recorded.","options":["discrepancies","desperations","dispensations","discriminations"],"answer":0,"explanation":"A discrepancy is a mismatch between two things that should agree, such as invoices and payments. The others look similar but mean something else.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-43","question":"Fill in the blank.\nAnanya is one of those analysts who ___ never missed a deadline.","options":["has","have","had been","is"],"answer":1,"explanation":"The relative pronoun 'who' refers to 'analysts' (the group she belongs to), so the verb is plural: 'who have never missed'. 'Has' wrongly agrees with 'one'.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id": "apt-verbal-placement-44", "question": "How many of the following sentences are grammatically correct?\n(i) The data are being analysed by the research team.\n(ii) Scarcely had we reached the venue when it started raining.\n(iii) It is high time we leave for the airport.\n(iv) Neither of the two proposals is acceptable to the board.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i) 'data' as a plural is correct; (ii) scarcely … when is right; (iv) 'neither of' takes a singular verb. (iii) is wrong: 'It is high time' takes the past form, 'we left'. So three are correct.", "difficulty": "hard", "source": "Capgemini · AMCAT English pattern"},
  {"id": "apt-verbal-placement-45", "question": "Fill in the blank.\nThe client insisted that the revised report ___ submitted before Friday.", "options": ["was", "is", "be", "will be"], "answer": 2, "explanation": "Verbs of demand such as insist, recommend and suggest take the subjunctive (base form) in the that-clause: 'that the report be submitted'.", "difficulty": "hard", "source": "Capgemini · AMCAT English pattern"},
  {"id": "apt-verbal-placement-46", "question": "Fill in the blank.\nDouble-check the figures lest you ___ an error in the final invoice.", "options": ["would make", "will make", "do not make", "should make"], "answer": 3, "explanation": "'Lest' means 'for fear that' and is followed by 'should' + base verb (or the bare base form). It is already negative, so 'do not make' creates a double negative.", "difficulty": "moderate", "source": "Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-47","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: Yet the same feature that makes it cheap also makes it fragile.\nQ: Cloud storage has made it cheap for start-ups to keep every file they create.\nR: A single misconfigured setting can expose millions of records to anyone who looks.\nS: Files sit on shared servers that are reached over the public internet.","options":["QSPR","QPSR","QSRP","SQPR"],"answer":0,"explanation":"Q opens the topic; S explains how it works; P refers back to that 'feature' (shared, internet-reached servers); R gives the concrete risk. In QPSR, P's 'same feature' has nothing to point to.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-48","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nThe first and last sentences are fixed.\n1. Interview panels often favour candidates who answer quickly.\nP: Slower answers, by contrast, are sometimes read as a lack of knowledge.\nQ: Quick answers sound confident, and confidence is easily mistaken for competence.\nR: Several firms now give candidates a few minutes to think before they respond.\nS: In technical roles, however, the first answer is frequently not the best one.\n6. Early results suggest that this small change improves the quality of hires.","options":["QSPR","QPSR","SQPR","PQSR"],"answer":1,"explanation":"Q explains why quick answers win; P ('by contrast') covers slow answers; S ('however') challenges that bias; R gives the response, which sentence 6 calls 'this small change'.","difficulty":"hard","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-49","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: The second, and less obvious, is that it changes what customers expect.\nQ: A discount offered every month has two effects.\nR: The first is a short-term rise in sales.\nS: Once shoppers learn that a sale is always coming, they stop buying at full price.","options":["QRSP","RQPS","QRPS","QPRS"],"answer":2,"explanation":"Q announces two effects; R gives the first, P the second, and S explains the second. S cannot come before P because it illustrates the changed expectation.","difficulty":"hard","source":"TCS NQT verbal pattern"},
  {"id":"apt-verbal-placement-50","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: Most of them, however, never get past the first chapter.\nQ: Every January, sales of self-improvement books rise sharply.\nR: Publishers know this and time their biggest releases accordingly.\nS: The books are bought with good intentions, often as gifts to oneself.","options":["QSPR","RQSP","QSRP","QRSP"],"answer":3,"explanation":"R's 'this' and 'accordingly' point to the January sales spike in Q, so R follows Q directly. S describes the buying, and P ('however', 'them' = the books) gives the contrast.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-51","question":"Read the passage and answer the question.\n\nPassage: When the firm moved half its support staff to remote work, managers expected productivity to fall. Instead, ticket resolution times improved by about a tenth within six months. Exit interviews, however, told a different story: newer employees reported feeling isolated and said they had learned the job more slowly without colleagues nearby. The company has since asked recent hires to spend three days a week in the office, while experienced staff may continue to work from home.\n\nWhich of the following, if true, would most weaken the reason for the company's new policy on recent hires?","options":["New hires who worked from the office learned the job no faster than new hires who worked from home.","Several newer employees who left cited isolation as a reason.","Office rents in the city have risen over the past year.","Experienced staff resolved tickets faster from home than from the office."],"answer":0,"explanation":"The policy rests on the idea that recent hires learn faster in the office. Evidence that they do not learn faster there removes that reason. The last option strengthens the policy; the others are irrelevant to it.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-52","question":"Read the passage and answer the question.\n\nPassage: For decades, manufacturers prized lean inventories: every part arrived just before it was needed, and warehouses shrank. The approach cut storage costs, but it left little room for error. When a single supplier halted production, entire assembly lines stood idle within days. Many firms now keep a modest buffer of critical components, accepting higher holding costs as the price of resilience. Critics argue this merely shifts risk to the balance sheet; supporters reply that an idle factory costs far more than a full warehouse.\n\nEach of the following is supported by the passage EXCEPT:","options":["Keeping a buffer of components raises holding costs.","Most firms have abandoned lean inventory methods entirely.","A halt at a single supplier could stop assembly lines.","Lean inventories reduced storage costs."],"answer":1,"explanation":"The passage says many firms now keep 'a modest buffer of critical components', which is a partial change, not abandoning lean methods entirely. The other three are stated directly.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-53","question":"Read the passage and answer the question.\n\nPassage: A mid-sized software company banned internal meetings on Wednesdays. The rule was meant to give engineers long stretches of uninterrupted time. After a quarter, the number of code changes shipped on Wednesdays rose sharply, but so did the volume of internal chat messages, as staff tried to settle by text what they would once have settled in a ten-minute call. Some team leads now argue that the policy did not remove coordination costs; it only moved them.\n\nThe team leads' argument assumes which of the following?","options":["The rise in code changes was caused by the extra chat messages.","Meetings on other days became shorter.","The extra chat messages on Wednesdays were largely doing the coordination work that meetings used to do.","Engineers prefer chat to meetings."],"answer":2,"explanation":"To say the costs were 'moved', the leads must assume the new messages replace the coordination that meetings did, not unrelated chatter. If the messages were social, their argument fails.","difficulty":"hard","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-54","question":"Read the passage and answer the question.\n\nPassage: A retailer found that customers who left a complaint and received a reply within an hour were more likely to buy again than customers who never complained at all. The finding surprised the board, which had treated complaints purely as a cost. The marketing head cautions against reading too much into it: customers who bother to complain may simply be more engaged with the brand to begin with.\n\nThe marketing head's point is best described as which of the following?","options":["Complaints should be ignored because they are costly.","Customers who never complain are the most loyal.","Quick replies to complaints reduce repeat sales.","The link between complaining and buying again may reflect customers who were already more loyal, not the effect of the quick reply."],"answer":3,"explanation":"The head warns that complainers may differ from non-complainers from the start (more engaged), so the reply may not be what causes the repeat purchases. This is a correlation-versus-cause caution.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-55","question":"Read the passage and answer the question.\n\nPassage: A retailer found that customers who left a complaint and received a reply within an hour were more likely to buy again than customers who never complained at all. The finding surprised the board, which had treated complaints purely as a cost. The marketing head cautions against reading too much into it: customers who bother to complain may simply be more engaged with the brand to begin with.\n\nWhich of the following, if true, would most strengthen the marketing head's caution?","options":["Customers who complained but got no reply for a week also bought again more often than customers who never complained.","Customers who got a quick reply bought again more often than complainers who got a slow reply.","The retailer cut its complaint-handling budget last year.","Customers who received a reply within an hour rated the service highly."],"answer":0,"explanation":"If even ignored complainers buy again more than non-complainers, the engagement of complainers, not the quick reply, explains the pattern. The last option supports the reply effect, so it weakens the caution.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id": "apt-verbal-placement-56", "question": "Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe CEO, as well as the directors, / were present / when the merger was announced. / No error", "options": ["The CEO, as well as the directors,", "were present", "when the merger was announced", "No error"], "answer": 1, "explanation": "'As well as the directors' is a parenthetical add-on; the subject is 'The CEO' (singular), so 'was present'.", "difficulty": "hard", "source": "Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-57","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nBeing a rainy day, / the offsite was postponed / to Friday. / No error","options":["to Friday","the offsite was postponed","Being a rainy day,","No error"],"answer":2,"explanation":"As written, 'Being a rainy day' describes 'the offsite', which is absurd. It needs its own subject: 'It being a rainy day, the offsite was postponed'.","difficulty":"hard","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-58","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nBetween you and I, / the appraisal results will be announced / only after the board meeting. / No error","options":["No error","the appraisal results will be announced","only after the board meeting","Between you and I,"],"answer":3,"explanation":"A preposition (between) takes the object case: 'between you and me'. 'You and I' sounds formal, which is why it slips through.","difficulty":"hard","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-59","question":"Which of the following sentences is correct?","options":["Of the two candidates, Priya is the more qualified.","Priya is the more qualified of all the candidates.","Of the two candidates, Priya is the most qualified.","Priya is more qualified than any candidate on the shortlist."],"answer":0,"explanation":"Two items take the comparative (the more qualified). 'Than any candidate' must be 'than any other candidate' when Priya is on the shortlist herself; 'of all' needs the superlative.","difficulty":"hard","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-60","question":"Fill in the blank.\nBy the time the auditors arrive tomorrow, we ___ the reconciliation.","options":["would complete","will have completed","have completed","will complete"],"answer":1,"explanation":"An action finished before a future point ('by the time … arrive') takes the future perfect: 'will have completed'.","difficulty":"hard","source":"TCS NQT verbal pattern"},
  {"id": "apt-verbal-placement-61", "question": "Fill in the blank.\nHad the team tested the patch on the staging server, the outage ___.", "options": ["will have been avoided", "had been avoided", "would have been avoided", "would be avoided"], "answer": 2, "explanation": "'Had the team tested' is an inverted third conditional (= If the team had tested), whose result clause is 'would have + past participle'.", "difficulty": "hard", "source": "Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-62","question":"Which sentence uses 'fewer' and 'less' correctly?","options":["Our team has fewer staff but less problems.","There were less complaints this quarter than last.","Fewer water was used after the new taps were fitted.","We received fewer applications this year, and the hiring budget is also less."],"answer":3,"explanation":"'Fewer' goes with countable plurals (applications, complaints, problems) and 'less' with uncountable nouns (budget as an amount, water).","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-63","question":"Fill in the blank.\nThe CFO's statement was meant to ___ fears of layoffs among the staff.","options":["allay","ally","allure","alley"],"answer":0,"explanation":"To allay fears is to reduce or calm them. Alley (a lane), ally (to join with) and allure (to attract) are look-alikes.","difficulty":"moderate","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id": "apt-verbal-placement-64", "question": "In how many of the following sentences is the idiom used correctly?\n(i) The new hire is still learning the ropes in her first month.\n(ii) After a bitter quarrel, the two teams let the cat out of the bag and worked well together.\n(iii) The manager gave the proposal the green light, so the project was cancelled.\n(iv) We will cross that bridge when we come to it.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "(i) learning the ropes = learning how a job is done, correct. (iv) = deal with a problem only when it arises, correct. (ii) letting the cat out of the bag means revealing a secret, not making peace (that is 'bury the hatchet'). (iii) a green light means approval, which contradicts 'cancelled'. So two.", "difficulty": "hard", "source": "Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-65","question":"In which sentence is the word used INCORRECTLY?","options":["Please be discreet when discussing the client's finances.","The manager made a discrete enquiry about the candidate's notice period.","The process is broken into discrete steps, each with its own owner.","The survey responses were grouped into five discrete categories."],"answer":1,"explanation":"Discreet = careful not to attract attention; discrete = separate and distinct. A quiet enquiry is a 'discreet' enquiry.","difficulty":"hard","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-66","question":"Choose the pair of words that best fills the blanks.\nHer ___ explanation, far from clarifying the issue, only ___ the confusion.","options":["lucid … dispelled","convoluted … dispelled","convoluted … compounded","lucid … compounded"],"answer":2,"explanation":"'Far from clarifying' tells us the explanation failed, so it was convoluted (overly complicated), and the confusion grew (compounded). 'Lucid … compounded' breaks the logic of the first blank.","difficulty":"hard","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-67","question":"Which of the following sentences uses 'no sooner' correctly?","options":["No sooner the CEO announced the bonus than the shares rose.","No sooner had the CEO announced the bonus then the shares rose.","No sooner had the CEO announced the bonus when the shares rose.","No sooner did the CEO announce the bonus than the shares rose."],"answer":3,"explanation":"'No sooner' needs inversion (did/had + subject) and pairs with 'than'. The others use 'when', drop the inversion, or confuse 'than' with 'then'.","difficulty":"hard","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-68","question":"Fill in the blank.\nThe jury ___ divided in their opinions, so the verdict was delayed.","options":["were","is","was","has been"],"answer":0,"explanation":"A collective noun takes a plural verb when its members act as individuals; 'divided' and 'their opinions' show that here. 'Was' would clash with 'their'.","difficulty":"hard","source":"Wipro NLTH · Cognizant GenC pattern"},
  {"id":"apt-verbal-placement-69","question":"Fill in the blanks.\nThe manager was angry ___ his assistant ___ the delay in the report.","options":["on … at","with … for","upon … with","to … about"],"answer":1,"explanation":"One is angry with a person and angry for (or about) a thing. The other pairs misuse the prepositions.","difficulty":"moderate","source":"Capgemini · AMCAT English pattern"},
  {"id": "apt-verbal-placement-70", "question": "Choose the word opposite in meaning to the word in capitals.\nThe new backup protocol is meant to MITIGATE the risk of data loss.", "options": ["Insure", "Alleviate", "Aggravate", "Assess"], "answer": 2, "explanation": "Mitigate means to make less severe; aggravate means to make worse. Alleviate is a synonym, the usual trap.", "difficulty": "hard", "source": "Wipro NLTH · Cognizant GenC pattern"},
  {"id": "apt-verbal-placement-71", "question": "Choose the word closest in meaning to the word in capitals.\nThe meeting was OSTENSIBLY about budgets, but most of the time went on the reorganisation.", "options": ["Actually", "Mainly", "Secretly", "Seemingly"], "answer": 3, "explanation": "Ostensibly means 'as it appears or is claimed', i.e. seemingly; the 'but' shows the real purpose was different. 'Actually' is close to the opposite.", "difficulty": "hard", "source": "Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-72","question":"Choose the correct indirect form of: She said to me, \"Will you send me the file tomorrow?\"","options":["She asked me if I would send her the file the next day.","She told me whether I would send her the file the next day.","She asked me would I send her the file the next day.","She asked me if I will send her the file tomorrow."],"answer":0,"explanation":"A yes/no question is reported with asked + if/whether, statement word order, will → would, me → her and tomorrow → the next day. 'Told' cannot introduce a question.","difficulty":"moderate","source":"TCS NQT verbal pattern"},
  {"id": "apt-verbal-placement-73", "question": "Choose the correct passive form of: \"Who has approved this expense?\"", "options": ["By who has this expense been approved?", "By whom was this expense approved?", "By whom this expense has been approved?", "By whom has this expense been approved?"], "answer": 3, "explanation": "'Who' as the doer becomes 'by whom'; the present perfect stays 'has been + past participle' with question word order. The second option changes the tense, the third loses the question order, and the fourth uses 'who' after a preposition.", "difficulty": "moderate", "source": "TCS NQT verbal pattern"},
  {"id":"apt-verbal-placement-74","question":"Choose the most concise and professional rewrite of:\n\"I am writing this email to you in order to inform you that the meeting which was scheduled for Monday has been moved to Tuesday due to the fact that the client is unavailable.\"","options":["I am writing to inform you that the meeting scheduled for Monday has been moved to Tuesday due to the fact that the client is unavailable.","The Monday meeting has been moved to Tuesday because the client is unavailable.","FYI, Monday's meeting is now Tuesday, client can't make it.","Meeting moved."],"answer":1,"explanation":"The best version keeps every fact (which meeting, new day, reason) and removes padding ('in order to', 'due to the fact that'). The third is still wordy, the second is too casual, and the last drops information.","difficulty":"moderate","source":"Infosys · Accenture verbal pattern"},
  {"id":"apt-verbal-placement-75","question":"Which sentence uses 'who' or 'whom' correctly?","options":["The analyst whom I believed was on leave joined the call.","To who should the invoice be addressed?","The analyst who I believed was on leave joined the call.","The client whom requested the refund has written again."],"answer":2,"explanation":"In the first, 'who' is the subject of 'was on leave' ('I believed' is an inserted clause), so 'who' is right and 'whom' in the second is wrong. 'Whom requested' needs the subject form, and 'to who' needs the object form 'whom'.","difficulty":"hard","source":"Capgemini · AMCAT English pattern"},
  {"id":"apt-verbal-placement-76","question":"Choose the word closest in meaning to the word in capitals.\nThe new intern was DILIGENT in documenting every test case.","options":["Hard-working","Careless","Reluctant","Talkative"],"answer":0,"explanation":"Diligent means showing steady, careful effort, i.e. hard-working. Careless is its opposite.","difficulty":"easy","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-77","question":"Choose the word opposite in meaning to the word in capitals.\nThe manager gave a VAGUE reply when asked about the appraisal dates.","options":["Unclear","Precise","Rude","Brief"],"answer":1,"explanation":"Vague means not clearly stated; its opposite is precise. Unclear is a synonym, and a reply can be brief yet still clear or vague.","difficulty":"easy","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-78","question":"Fill in the blank with the correct preposition.\nDue to the server migration, the client demo has been postponed ___ next Monday.","options":["at","with","to","from"],"answer":2,"explanation":"An event is postponed TO a later date. “Postponed at/with/from” is not idiomatic.","difficulty":"easy","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-79","question":"Choose the one word for: a person or company that is unable to pay its debts.","options":["Insolent","Illiterate","Introvert","Insolvent"],"answer":3,"explanation":"Insolvent means unable to pay debts. Insolent (rude and disrespectful) is the look-alike trap.","difficulty":"easy","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-80","question":"Fill in the blank.\nI ___ in this company since 2021, and I have worked on three products so far.","options":["have been working","am working","was working","work"],"answer":0,"explanation":"“Since 2021” marks an action that began in the past and continues now, which needs the present perfect continuous: have been working. “Am working since” is a common Indian-English error.","difficulty":"moderate","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-81","question":"Fill in the blanks with the correct articles.\n___ European client and ___ Indian vendor signed the contract yesterday.","options":["An, an","A, an","An, a","A, a"],"answer":1,"explanation":"Articles follow the sound, not the letter: “European” begins with a “yoo” (consonant) sound, so “a European”; “Indian” begins with a vowel sound, so “an Indian”.","difficulty":"moderate","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-82","question":"Choose the meaning of the idiom in capitals.\nThe pilot failed badly, so the product team had to GO BACK TO THE DRAWING BOARD.","options":["Ask the design team for more drawings","Give up the project for good","Start planning again from the beginning","Blame the designers for the failure"],"answer":2,"explanation":"“Go back to the drawing board” means to start again after a plan has failed. It does not mean abandoning the project or literal drawings.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-83","question":"Choose the correct passive form of: \"The QA team is testing the new release.\"","options":["The new release is tested by the QA team.","The new release has been tested by the QA team.","The new release was being tested by the QA team.","The new release is being tested by the QA team."],"answer":3,"explanation":"Present continuous active (is testing) becomes present continuous passive: is being + past participle. The other options change the tense.","difficulty":"easy","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-84","question":"Choose the correct indirect form of: He said, \"I will submit the report tomorrow.\"","options":["He said that he would submit the report the next day.","He said that he will submit the report tomorrow.","He said that I would submit the report the next day.","He said that he would have submitted the report tomorrow."],"answer":0,"explanation":"With a past reporting verb, “will” becomes “would”, “I” becomes “he”, and “tomorrow” becomes “the next day”. Keeping “will … tomorrow” ignores the backshift.","difficulty":"easy","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-85","question":"Which word is spelt correctly?","options":["Occurence","Occurrence","Ocurrence","Occurrance"],"answer":1,"explanation":"“Occurrence” has double c, double r, and ends in -ence. The other spellings drop a letter or use -ance.","difficulty":"moderate","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-86","question":"Fill in the blank.\nThe new analytics dashboard ___ the existing reporting tools rather than replacing them.","options":["compliments","completes","complements","competes"],"answer":2,"explanation":"“Complement” means to complete or go well with something; “compliment” means to praise. A dashboard that works alongside existing tools complements them.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-87","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nNeither of the two proposals were / accepted by the board, as both / exceeded the approved budget. / No error","options":["Neither of the two proposals were","accepted by the board, as both","exceeded the approved budget.","No error"],"answer":0,"explanation":"“Neither of” takes a singular verb: “Neither of the two proposals was accepted”. The plural “proposals” right before the verb is the trap.","difficulty":"moderate","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-88","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe manager, along with his team, / are attending the client meeting / in Bengaluru this week. / No error","options":["The manager, along with his team,","are attending the client meeting","in Bengaluru this week.","No error"],"answer":1,"explanation":"The subject is “The manager”; a phrase starting with “along with” does not make it plural. So it should be “is attending”.","difficulty":"moderate","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-89","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nHardly had the server restarted / when the alerts started / flooding the dashboard. / No error","options":["Hardly had the server restarted","when the alerts started","flooding the dashboard.","No error"],"answer":3,"explanation":"The sentence is correct: “Hardly … when” is the right pair, and the inversion “had the server restarted” is required after “Hardly”. Changing “when” to “than” would create an error (“than” goes with “no sooner”).","difficulty":"moderate","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-90","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nIf he would have checked the logs, / he could have found / the bug much earlier. / No error","options":["If he would have checked the logs,","he could have found","the bug much earlier.","No error"],"answer":0,"explanation":"In a third conditional the if-clause takes the past perfect: “If he had checked the logs, he could have found …”. “Would have” belongs only in the main clause.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-91","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: As a result, many teams now insist that every change be reviewed by at least one other engineer.\nQ: Studies of software projects have repeatedly found that defects caught early are far cheaper to fix than those found later.\nR: Code review is one of the cheapest ways of catching such defects before they reach production.\nS: However, reviews work only if reviewers have the time to read each change carefully.","options":["RQPS","QPRS","QRPS","SQRP"],"answer":2,"explanation":"Q states the general finding; R introduces code review as a way to catch “such defects” (refers back to Q); P gives the result (“As a result”); S adds a qualification with “However”. QPRS puts the result before its cause.","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-92","question":"Arrange the sentences P, Q, R and S in the most logical order to form a coherent paragraph.\nP: For twenty years, the bakery had relied entirely on customers who walked past its door.\nQ: Today, online orders make up more than half of its revenue.\nR: Orders that once came only from the neighbourhood began arriving from across the city.\nS: During the lockdown, with footfall gone, the owner reluctantly listed her cakes on a delivery app.","options":["PSRQ","PRSQ","SPRQ","PSQR"],"answer":0,"explanation":"P sets the background, S is the turning point (lockdown, listing online), R is the immediate effect, and Q (“Today”) is the present outcome. PRSQ has orders arriving from across the city before the bakery went online.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-93","question":"Choose the word that best fills the blank.\nAlthough the startup’s revenue grew rapidly, its ___ spending on marketing meant that it was still losing money.","options":["frugal","prudent","negligible","unchecked"],"answer":3,"explanation":"“Although revenue grew … still losing money” needs a word for excessive spending: unchecked. Frugal, prudent and negligible all describe careful or small spending, which would not explain the losses.","difficulty":"moderate","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-94","question":"Choose the pair of words that best fills the blanks.\nThe auditor’s report was ___: it praised the team’s diligence but ___ the lack of proper documentation.","options":["glowing, overlooked","scathing, ignored","neutral, applauded","mixed, criticised"],"answer":3,"explanation":"The colon promises a description that the second half explains: praise “but” criticism = a mixed report. “Glowing … overlooked” loses the contrast signalled by “but”; “scathing” clashes with “praised”.","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-95","question":"Choose the best replacement for the sentence, or the option that corrects it.\n\"The reason why he resigned is because he was overworked.\"","options":["The reason he resigned is that he was overworked.","The reason why he resigned was because of overwork.","The reason he resigned is because of he was overworked.","No improvement needed"],"answer":0,"explanation":"“The reason … is because” is redundant, since “reason” already means cause; the standard form is “The reason … is that …”. The other rewrites keep the redundancy or break the grammar.","difficulty":"moderate","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-96","question":"In which sentence is the word \"discreet\" or \"discrete\" used correctly?","options":["The signal is sampled at discreet intervals.","Please be discreet when discussing the restructuring with the team.","She made a discrete enquiry about the vacancy.","The project was split into three discreet phases."],"answer":1,"explanation":"“Discreet” means careful not to cause embarrassment or reveal secrets; “discrete” means separate or distinct. Intervals and phases are discrete; an enquiry made quietly is discreet.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-97","question":"Read the passage and answer the question.\n\nPassage: Many firms measure developer productivity by counting the lines of code written. The metric is easy to collect, but it rewards the wrong behaviour: a developer who deletes 500 redundant lines while keeping every feature working has arguably done more useful work than one who adds 500 new ones, yet the metric scores the first as negative. Worse, once engineers know they are measured this way, they tend to write longer code than necessary.\n\nWhich of the following can be inferred from the passage?","options":["Deleting code is always more valuable than writing new code.","Lines of code are difficult to count accurately.","A metric can change the very behaviour it is meant to measure.","Firms should stop measuring developer productivity altogether."],"answer":2,"explanation":"The last sentence says engineers write longer code once they know the metric, i.e. measurement changes behaviour. “Always more valuable” over-generalises a single example; the passage says the metric is EASY to collect; abandoning all measurement goes beyond the text.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-98","question":"A senior client proposes a review meeting on Friday, but you will be at another client’s site all day. Which reply is the most appropriate?","options":["Friday does not work for me. Let me know another day.","Sorry, I am very busy on Friday so I cannot come, please understand.","I will try to join on Friday if I get some time between my other meetings.","Thank you for the invitation. I will be at another client site on Friday; could we meet on Monday or Tuesday instead? I am happy to work around your schedule."],"answer":3,"explanation":"The best reply thanks the client, gives a brief reason, and proposes concrete alternatives while staying flexible. The others are curt, vague and apologetic without a solution, or non-committal in a way that risks a no-show.","difficulty":"moderate","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-99","question":"The first and last sentences of a paragraph are fixed. Arrange P, Q, R and S in between to form a coherent paragraph.\n1: A large online retailer once noticed that its sales dipped sharply every Friday evening.\nP: Then someone laid the sales graph over the server-load graphs.\nQ: The cause turned out to be a weekly database backup that started at 7 p.m.\nR: Moving the backup to 3 a.m. made the dip disappear within a week.\nS: Engineers first suspected a marketing problem, but the campaigns ran the same on every day.\n6: The lesson: before blaming customers, check your own systems.","options":["SQPR","PSQR","SPRQ","SPQR"],"answer":3,"explanation":"S is the first (wrong) hypothesis; P (“Then”) is the next step in the investigation; Q reveals what that comparison showed; R is the fix, which leads to the lesson in 6. SQPR reveals the cause before the step that found it.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-100","question":"Three of the four sentences below form a coherent paragraph. Which sentence does NOT belong?\nA. Cloud providers bill most services by the hour or even by the second.\nB. This lets a startup pay only for the computing it actually uses instead of buying servers upfront.\nC. Many startups also rent their office space by the month rather than buying property.\nD. The flip side is that a forgotten test server can quietly run up a large bill.","options":["A","B","D","C"],"answer":3,"explanation":"A, B and D form a tight argument about cloud billing: how it works, its benefit (“This lets …”), and its risk (“The flip side …” refers to the pay-per-use model). C shifts to office rent; it shares the pay-as-you-go idea but breaks the topic, and D cannot follow it.","difficulty":"hard","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-101","question":"Read the passage and answer the question.\n\nPassage: The vendor’s proposal promises \"zero downtime\", \"infinite scalability\" and \"fully automated security\". Each phrase is attractive; none is defined. The document runs to forty pages, yet it never says what happens when a data centre fails, how costs grow with traffic, or who is accountable when an automated control misses an attack. Perhaps the vendor has good answers. The proposal, however, gives us no way of knowing.\n\nThe author’s attitude towards the proposal is best described as:","options":["Sceptical","Enthusiastic","Indifferent","Contemptuous"],"answer":0,"explanation":"The author questions undefined claims and lists missing details, yet concedes the vendor “perhaps” has answers — measured doubt, i.e. scepticism. Contemptuous is too strong given that concession; indifferent ignores the detailed critique.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-102","question":"Read the passage and answer the question.\n\nPassage: A food-delivery company found that customers who ordered at least three times in their first week were far more likely to still be using the app six months later. The product team therefore proposed giving every new user three free deliveries in their first week, expecting long-term retention to rise.\n\nThe proposal depends on which assumption?","options":["Free deliveries cost the company very little.","Ordering often in the first week helps cause long-term use, rather than merely signalling users who would have stayed anyway.","Every new user will place exactly three orders in the first week.","Six months is the most useful period over which to measure retention."],"answer":1,"explanation":"The data shows only a correlation. The plan works only if early ordering itself drives retention; if keen users simply order more, free deliveries would not change who stays. Cost, exact order counts and the measurement window are not required for the reasoning.","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-103","question":"Choose the sentence that best completes the paragraph.\nAutomated tests catch regressions quickly, but they check only what someone thought to test. Exploratory testing, in which a tester probes the software without a script, often finds the bugs that nobody anticipated. ___","options":["Automated testing should therefore be abandoned.","Exploratory testing is therefore cheaper than automation.","The two approaches therefore complement each other rather than compete.","Most bugs are therefore found by customers after release."],"answer":2,"explanation":"The paragraph gives each approach a distinct strength, so the natural conclusion is that they work together. Abandoning automation contradicts the first sentence; cost and customer-found bugs are never discussed.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-104","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nScarcely had the review meeting begun / than the fire alarm / went off on the third floor. / No error","options":["Scarcely had the review meeting begun","than the fire alarm","went off on the third floor.","No error"],"answer":1,"explanation":"“Scarcely” (like “hardly”) pairs with “when”, not “than”: “Scarcely had the meeting begun when the fire alarm went off.” “Than” belongs with “no sooner”. The inversion in the first part is correct.","difficulty":"hard","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-105","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nBeing a public holiday, / the office remained / closed all day. / No error","options":["the office remained","Being a public holiday,","closed all day.","No error"],"answer":1,"explanation":"The opening participle has no proper subject: as written, it says the office was a public holiday. Correct: “It being a public holiday, the office remained closed” or “As it was a public holiday, …”.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-106","question":"Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe selection panel comprises of / five senior engineers / and two external experts. / No error","options":["five senior engineers","and two external experts.","No error","The selection panel comprises of"],"answer":3,"explanation":"“Comprise” takes a direct object: “The panel comprises five senior engineers …”, or “is composed of / consists of”. “Comprises of” is a common error.","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-107","question":"Fill in the blank.\nThe attrition numbers are alarming; it is high time the company ___ its leave policy.","options":["revised","revises","revise","has revised"],"answer":0,"explanation":"“It is high time” is followed by the past simple (a subjunctive use) to show that the action is overdue: “it is high time the company revised …”. The present forms sound natural but are grammatically wrong here.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-verbal-placement-108","question":"How many of the following sentences are grammatically correct?\n(i) Every one of the servers was patched last night.\n(ii) The CEO, as well as the directors, were present at the meeting.\n(iii) Neither the laptops nor the charger was delivered on time.\n(iv) One of my colleague is on leave today.","options":["1","2","3","4"],"answer":1,"explanation":"(i) Correct: “every one” is singular. (ii) Wrong: “as well as” does not add to the subject, so “The CEO … was present”. (iii) Correct: with “neither … nor”, the verb agrees with the nearer subject, “charger” → was. (iv) Wrong: “one of my colleagues”. Two are correct.","difficulty":"hard","source":"Infosys · Capgemini pattern"},
  {"id":"apt-verbal-placement-109","question":"Choose the word closest in meaning to the word in capitals.\nThe vendor’s OBSEQUIOUS emails, full of flattery and endless apologies, began to irritate the CTO.","options":["Insolent","Sincere","Servile","Obscure"],"answer":2,"explanation":"Obsequious means excessively eager to please or obey — servile. Insolent is the opposite; obscure is a sound-alike trap.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-verbal-placement-110","question":"Which sentence uses \"lie\" or \"lay\" correctly?","options":["After the night shift yesterday, she lay down for an hour.","After the night shift yesterday, she laid down for an hour.","Please lie the files on my desk before you leave.","The signed documents have laid untouched for weeks."],"answer":0,"explanation":"“Lie” (recline, no object) has past “lay” and participle “lain”; “lay” (put something down, takes an object) has past “laid”. So: she lay down (correct); she laid down (wrong); lay the files (not lie); have lain untouched (not laid).","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-verbal-placement-111","question":"Read the passage and answer the question.\n\nPassage: When a ride-hailing platform cut its commission from 25% to 15% in one city, driver sign-ups rose by 40% within two months. Yet the average driver's earnings per hour fell. The platform's analysts noted that the number of ride requests had stayed flat over the period, and that the share of each shift drivers spent waiting for a booking had nearly doubled.\n\nQuestion: Which of the following is best supported by the passage?","options":["The cut drew so many new drivers that the same number of rides was spread thinner, reducing each driver's paid time.","The commission cut was a loss-making decision for the platform.","Drivers who joined after the cut were less skilled than earlier drivers.","Riders did not notice the commission cut because fares did not change."],"answer":0,"explanation":"Flat demand + many more drivers + doubled waiting time together point to dilution: the same rides shared by more drivers, so each spends less of the shift earning. A lower commission alone would raise per-ride income, so something must have offset it — idle time. The passage says nothing about the platform's profits, driver skill or rider awareness; those options import outside assumptions.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-112","question":"Read the passage and answer the question.\n\nPassage: When a ride-hailing platform cut its commission from 25% to 15% in one city, driver sign-ups rose by 40% within two months. Yet the average driver's earnings per hour fell. The platform's analysts noted that the number of ride requests had stayed flat over the period, and that the share of each shift drivers spent waiting for a booking had nearly doubled.\n\nQuestion: Based on the passage, which step would most directly raise drivers' hourly earnings, assuming the commission stays at 15%?","options":["Cutting the commission further to 10%","Increasing ride requests or slowing the onboarding of new drivers","Paying a one-time bonus to every driver who joined after the cut","Publishing average hourly earnings to attract still more drivers"],"answer":1,"explanation":"Hourly earnings fell because waiting time doubled while demand stayed flat. The lever is therefore the ratio of rides to drivers: more requests or fewer new drivers. A further commission cut (tempting, since the first one was 'driver-friendly') would attract even more drivers and deepen the idle-time problem; publicising earnings has the same effect; a one-time bonus does not change hourly earnings.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-113","question":"Read the passage and answer the question.\n\nPassage: Historians long read the steep fall in recorded crop yields in a fourteenth-century province as evidence of famine. But in the same decades the province switched from taxing harvests to taxing land area. Under the new system a landholder gained nothing by reporting his output accurately and risked nothing by understating it, so the yield records — kept by tax collectors who no longer needed them — lost their link to what was actually harvested.\n\nQuestion: Which of the following best states the author's main point?","options":["There was no famine in the province during the fourteenth century.","Taxing land area is a fairer system than taxing harvests.","The recorded fall in yields may reflect a change in reporting incentives rather than a real fall in harvests.","Tax collectors deliberately falsified the yield records to hide a famine."],"answer":2,"explanation":"The author does not deny a famine outright; the claim is that the records stopped measuring harvests once the tax no longer depended on them, so they cannot prove a famine. 'There was no famine' overstates the argument (the most tempting trap). Fairness of taxes is never discussed, and the passage blames incentives, not deliberate falsification.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-114","question":"Read the passage and answer the question.\n\nPassage: Historians long read the steep fall in recorded crop yields in a fourteenth-century province as evidence of famine. But in the same decades the province switched from taxing harvests to taxing land area. Under the new system a landholder gained nothing by reporting his output accurately and risked nothing by understating it, so the yield records — kept by tax collectors who no longer needed them — lost their link to what was actually harvested.\n\nQuestion: Which of the following, if true, would most strengthen the author's argument?","options":["Neighbouring provinces that made the same switch to land taxes recorded no fall in yields.","Several landholders petitioned against the land tax, calling it heavy.","Tax collectors in the province were paid a fixed salary throughout the period.","Grain prices in the province's markets stayed stable throughout those decades, whereas they rose sharply during documented famines elsewhere."],"answer":3,"explanation":"Stable prices are independent evidence that real supply did not collapse, which is exactly what the author needs: the records fell, the harvest did not. If neighbouring provinces made the same switch without a recorded fall, the switch does not seem to distort records — that weakens the argument. Complaints about the tax and the collectors' pay do not bear on whether the records tracked real output.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-115","question":"Read the passage and answer the question.\n\nPassage: Chess masters shown a position from a real game for five seconds can reconstruct it almost perfectly, while novices recall only a handful of pieces. When the same number of pieces is scattered randomly on the board, however, masters do barely better than novices.\n\nQuestion: Which conclusion is most strongly supported?","options":["The masters' advantage comes from recognising meaningful patterns rather than from greater raw memory capacity.","Masters have a generally superior visual memory compared with novices.","Masters remember random positions worse than novices do.","Novices could become masters by practising the memorisation of random positions."],"answer":0,"explanation":"The advantage appears only when the position is meaningful, so it must depend on knowledge of typical structures, not on general memory. 'Superior visual memory' is contradicted by the random-position result; 'worse than novices' overstates 'barely better'; and nothing suggests memorising random positions builds expertise — if anything the data suggest it would not help.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-116","question":"Read the passage and answer the question.\n\nPassage: Open-plan offices were sold as engines of collaboration: tear down the walls, the argument went, and the barriers between people would fall with them. Yet when researchers fitted employees at two firms with sensors before and after such a move, face-to-face conversation fell by roughly two-thirds while email and chat messages rose sharply. Deprived of privacy, workers seem to have rebuilt it digitally.\n\nQuestion: The author's attitude towards the claim that open-plan offices increase collaboration is best described as:","options":["neutral: the author merely reports a study without judging the claim","sceptical: the author presents evidence that the promised effect did not occur","hostile to all forms of office redesign","convinced that digital communication harms productivity"],"answer":1,"explanation":"'Were sold as', 'the argument went' and the contrasting 'Yet' signal distance from the claim, and the evidence cuts against it — that is scepticism. It is not neutral (the framing takes a side), not a blanket attack on redesign, and the passage never says digital messaging hurts productivity; it only says it replaced talk.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-117","question":"Read the passage and answer the question.\n\nPassage: Open-plan offices were sold as engines of collaboration: tear down the walls, the argument went, and the barriers between people would fall with them. Yet when researchers fitted employees at two firms with sensors before and after such a move, face-to-face conversation fell by roughly two-thirds while email and chat messages rose sharply. Deprived of privacy, workers seem to have rebuilt it digitally.\n\nQuestion: The final sentence of the passage most likely implies that:","options":["employees preferred email because it is faster than conversation","the firms' managers banned face-to-face conversation after the move","employees used written messages partly to keep their exchanges from being overheard","the sensors interfered with normal conversation"],"answer":2,"explanation":"'Deprived of privacy, workers seem to have rebuilt it digitally' means the move to messages was a way of regaining privacy that the open floor removed. Speed of email is not mentioned; nothing suggests a ban; and blaming the sensors would undercut the study rather than explain the result, which is not what the author implies.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-118","question":"Critical reasoning. A company found that teams using its new code-review tool shipped 30% fewer bugs than teams that did not. The tool was offered to all teams, but adoption was voluntary, and the earliest adopters were teams whose leads had already made automated testing mandatory. The company concludes that the tool cuts bugs by about 30%. Which of the following best describes the main weakness of this conclusion?","options":["A 30% difference is too small to be meaningful.","Bugs differ in severity, so counting them is meaningless.","The tool may slow teams down and reduce the number of releases.","The adopting teams may have had fewer bugs anyway because of practices they already followed, so the difference cannot be credited to the tool alone."],"answer":3,"explanation":"Voluntary adoption by teams that already had mandatory testing is self-selection: the groups differed before the tool arrived, so the 30% gap mixes the tool's effect with existing discipline. The other options raise side issues (size, severity, speed) that do not touch the causal leap from correlation to effect.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-119","question":"Critical reasoning. After a town library extended its opening hours from 40 to 60 hours a week, the average number of visits per day fell, yet the total number of books borrowed per week rose. Which of the following, if true, best explains this?","options":["With longer hours, regular users switched from several short visits a week to a single longer visit in which they borrowed several books at once.","The library added a large number of new books at the same time.","Many visitors came only to use the library's free internet.","The library reduced the maximum number of books a member could borrow at a time."],"answer":0,"explanation":"The puzzle needs both facts at once: fewer visits but more borrowing. Fewer, longer visits with several books each explains both. New stock could raise borrowing but does not explain fewer visits; internet users are irrelevant to borrowing; a lower borrowing cap would push borrowing down, the opposite of what happened.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-120","question":"Critical reasoning. After a city installed red-light cameras at its 20 busiest junctions, the number of reported collisions at those junctions rose by 15%, yet insurance payouts for injuries from collisions there fell by 30%. Which of the following, if true, best resolves this apparent discrepancy?","options":["Drivers avoided the camera junctions and used side streets instead.","Drivers braking suddenly to avoid fines caused more minor rear-end bumps, while dangerous side-impact crashes from running red lights became much rarer.","Insurance companies raised their premiums across the city during the same period.","The cameras were switched off at night for maintenance."],"answer":1,"explanation":"More collisions but fewer injury payouts means the mix of collisions changed: many more low-severity crashes and fewer severe ones. Sudden braking explains the first and fewer red-light runners the second. Diverted traffic would reduce collisions, not raise them; premiums say nothing about payouts; night-time switch-offs do not explain the opposite movements.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-121","question":"Critical reasoning. An online-course provider reports that 90% of learners who paid for a course completed it, compared with 15% of learners who took it free. It therefore plans to stop offering free access, expecting the overall completion rate to rise to about 90%. The plan depends on which of the following assumptions?","options":["Most learners who now take courses free would agree to pay.","Completion is the best measure of how much a learner has learned.","The higher completion among payers is caused by having paid, rather than by the kind of learner who chooses to pay.","The price of the courses will not be raised in future."],"answer":2,"explanation":"The provider expects anyone who pays to behave like today's payers. That holds only if paying itself drives completion; if payers were simply the already-motivated learners, newly forced payers would complete at a lower rate. Whether most free learners pay changes how many enrol, not the completion rate among those who do; the other two options are not needed for the prediction.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-122","question":"Critical reasoning. The city council plans to end rush-hour congestion on its main road by widening it from two lanes to four. The council's reasoning assumes which of the following?","options":["Most rush-hour drivers on the road travel alone.","Widening the road will be cheaper than building a new rail line.","Congestion on the main road is worse than on any other road in the city.","The extra capacity will not simply attract enough additional trips to fill the road again."],"answer":3,"explanation":"If doubling capacity draws people who previously avoided the road (or travelled at other times), the new lanes fill up and congestion returns — the plan only works if that does not happen. Solo driving, cost comparisons and ranking against other roads are not needed for the conclusion that widening will end congestion on this road.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-123","question":"Critical reasoning. Ornithologists claim that a migratory songbird finds its way using the Earth's magnetic field. Which of the following, if true, most strongly supports this claim?","options":["Birds fitted with small magnets that distort the local field became disoriented under overcast skies, while birds fitted with brass weights of the same mass did not.","The birds fly the same route every year.","The birds migrate mostly at night.","Other species of bird are known to navigate using the positions of stars."],"answer":0,"explanation":"This is a controlled intervention: disturbing the magnetic field (and only that, since the brass weights control for the extra load) disrupts navigation when visual cues are hidden. A fixed route, night flying or other species' star navigation are consistent with many mechanisms and do not single out magnetism; star navigation even suggests an alternative.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-124","question":"Critical reasoning. In the year after a city launched a bike-sharing scheme, reported cases of asthma fell by 12%. The mayor argues that the scheme cut traffic pollution and so improved residents' health. Which of the following, if true, most seriously weakens the mayor's argument?","options":["Bike-sharing schemes in other cities have been popular.","In the same year the city's main hospital changed its coding rules, recording many former asthma cases as 'allergic bronchitis'.","Cycling is good exercise and improves heart health.","Some residents who use the bikes have asthma."],"answer":1,"explanation":"If the fall in 'asthma' is partly a relabelling of the same illnesses, the statistic does not show any real health improvement, let alone one caused by cleaner air. Popularity elsewhere and the heart benefits of exercise are irrelevant to asthma; asthmatic bike users do not affect the citywide count.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-125","question":"Critical reasoning. A survey found that employees who use standing desks report far fewer back problems than those who sit all day. The HR head proposes buying standing desks for all staff to reduce back problems. Which of the following, if true, most seriously weakens the proposal?","options":["Standing desks are more expensive than ordinary desks.","Some employees who use standing desks still sit for part of the day.","Employees who already had back problems were advised by their doctors not to use standing desks.","Back problems are a leading cause of sick leave."],"answer":2,"explanation":"This reverses the causal arrow: the desks did not prevent back problems; people with back problems were steered away from the desks. The correlation then says nothing about what the desks would do for everyone. Cost is a practical objection, not a logical weakness; partial sitting and the importance of back problems do not attack the inference.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-126","question":"Critical reasoning. Every project that met its deadline last year used the agile method. Some projects that used the agile method went over budget. No project that went over budget won an award. Which of the following must be true?","options":["Some projects that met their deadline went over budget.","No project that met its deadline won an award.","Every project that won an award used the agile method.","Some projects that used the agile method did not win an award."],"answer":3,"explanation":"The agile projects that went over budget exist (second statement), and none of them won an award (third statement), so some agile projects did not win. The first option may or may not be true — the over-budget agile projects need not be among those that met their deadline. Nothing links award winners to agile or forbids deadline-meeting projects from winning, so the last two are not forced.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-127","question":"Critical reasoning. Some economists argue that raising the minimum wage destroys low-wage jobs. [A] Yet in several regions that raised it sharply, employment in low-wage sectors held steady. The economists reply that employers adjusted in other ways, cutting hours and training instead of jobs. [B] If that is so, the right test of the policy is not the number of jobs but total hours worked and benefits received. In this argument, the sentences marked [A] and [B] play which roles?","options":["[A] is evidence against a position; [B] is the author's conclusion about how that position should be tested.","[A] is the conclusion of the argument; [B] is evidence for it.","[A] is the economists' main claim; [B] is a concession the author makes to them.","[A] and [B] are both pieces of evidence for the economists' position."],"answer":0,"explanation":"[A] reports a finding that cuts against the job-loss claim. The economists then shift ground, and [B] draws the author's conclusion: if adjustment happens through hours and benefits, those, not job counts, are the proper measure. [A] is not the conclusion and is not the economists' claim (their claim is in the first sentence); [B] does not concede anything to them — it reframes the test.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-128","question":"Critical reasoning. A city says that the 'quiet zones' it created last year cut noise complaints in those areas by 40%, so the zones have reduced noise. Which of the following would be most useful to know in evaluating this claim?","options":["How many residents support the quiet zones","Whether the way complaints are made — the hotline's hours or the online form — changed when the zones were introduced","How the city decided which areas would become quiet zones","Whether quiet zones in other countries have been popular with tourists"],"answer":1,"explanation":"The argument uses complaints as a stand-in for noise. If the complaint channel became harder to use at the same time, complaints could fall with no change in noise. That answer would directly confirm or undermine the measure. Public support and tourist popularity do not bear on noise levels; how the areas were chosen matters less than whether the measurement itself changed.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-129","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: The idea, however, sat unused for two decades, because the scanners needed to read it did not yet exist.\nQ: That packet now sits in a museum, an unlikely relic of a revolution in retail.\nR: In 1949 an engineering student sketched a code of thick and thin lines by drawing his fingers through beach sand.\nS: Today the same pattern is read billions of times a day, so routinely that shoppers no longer notice it.\nT: Cheap lasers and microchips changed that in the 1970s, and a supermarket finally scanned its first item, a packet of chewing gum.","options":["RTPQS","PRTQS","RPTQS","RPTSQ"],"answer":2,"explanation":"R introduces the idea (1949). P ('The idea, however, sat unused … scanners did not exist') must follow it. T ('changed that') answers P's missing scanners and introduces the packet of gum; Q ('That packet') must come right after T. S ('Today') closes the timeline. RPTSQ separates Q from the packet it refers to; RTPQS makes 'changed that' refer to nothing.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-130","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Newer studies suggest instead that the brain actively prunes memories it rarely uses.\nQ: Seen this way, the blank we sometimes draw on a name is the price of a memory that works.\nR: For a long time, psychologists treated forgetting as passive decay, like ink fading on paper.\nS: A system that stored every detail would, by contrast, drown in its own records.\nT: Pruning clears away clutter, so the memories that remain are quicker to retrieve.\nU: This is why people with near-perfect recall often describe it as a burden rather than a gift.","options":["RTPSUQ","PRTSUQ","RPSTUQ","RPTSUQ"],"answer":3,"explanation":"R gives the old view; P ('instead') gives the new one; T explains what pruning achieves; S ('by contrast') imagines the opposite system; U ('This is why') draws the consequence of S for people with perfect recall; Q ('Seen this way') sums up. RPSTUQ puts U after T, but 'This is why people with near-perfect recall … burden' explains S, not the benefits of pruning; PRTSUQ starts with 'instead', which needs the old view before it.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-131","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Ports that refused to adapt, by contrast, faded within a generation.\nQ: The steel shipping container, introduced in the 1950s, looks too simple to have changed the world.\nR: By packing goods into identical boxes that cranes could lift straight onto lorries and trains, it cut loading costs dramatically.\nS: Before it, cargo was loaded piece by piece, and a ship could spend longer in port than at sea.\nT: Cities that invested early in deep berths and giant cranes became the new hubs of world trade.","options":["QSRTP","QRSTP","QSRPT","SQRTP"],"answer":0,"explanation":"Q introduces the container; S ('Before it') describes the old system; R explains how the container cut costs; T names the winners; P ('by contrast') names the losers and must follow T. QSRPT puts 'by contrast' before anything it can contrast with; SQRTP opens with 'it' before the container is mentioned.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-132","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Within that narrow band, a difference of a tenth of a star can decide which product a shopper buys.\nQ: A five-star rating system seems to offer precise, graded feedback.\nR: Sellers, knowing this, chase tiny gains in their average rather than real improvements in quality.\nS: In practice, most users give either one star or five, treating the scale as a thumbs-up or thumbs-down.\nT: The middle of the scale is therefore nearly empty, and most averages cluster between 4.2 and 4.8.\nU: The precision the system promised has thus become a pressure that rewards gaming over substance.","options":["QTSPRU","QSTPRU","SQTPRU","QSTRPU"],"answer":1,"explanation":"Q states the promise; S ('In practice') shows how users actually behave; T ('therefore') draws the consequence — averages bunch together; P ('that narrow band') needs T's range; R ('knowing this') follows P's point that tiny differences matter; U ('thus') concludes. QTSPRU makes 'therefore' precede its reason; QSTRPU puts 'knowing this' before the fact it refers to.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-133","question":"Arrange the sentences in the most logical order to form a coherent paragraph.\nP: Each of these omissions is small on its own, but they compound.\nQ: Early estimates for software projects are notoriously optimistic.\nR: Managers then respond with pressure, and rushed work produces still more rework.\nS: Developers estimate the work they can see, not the integration, testing and rework that surface later.\nT: Ten tasks, each underestimated by a modest fifteen per cent, add up to a slip of weeks once the waiting between tasks is counted.","options":["QPSTR","QSTPR","QSPTR","SQPTR"],"answer":2,"explanation":"Q states the claim; S gives the cause and lists the omitted items; P ('Each of these omissions … compound') needs S's list; T illustrates the compounding; R ('then') describes the next stage, the managers' reaction to the slip. QPSTR uses 'these omissions' before any are named; QSTPR gives the example of compounding before the idea of compounding.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-134","question":"Four of the five sentences below form a coherent paragraph. Which sentence does NOT belong?\n1. Asphalt and dark roofs soak up sunlight during the day and release it slowly through the night.\n2. As a result, a city centre can stay several degrees warmer than the surrounding countryside after sunset.\n3. Rising sea levels, meanwhile, threaten coastal cities with more frequent flooding.\n4. Painting roofs white or planting street trees reflects or blocks much of this incoming energy.\n5. Several cities now offer rebates to building owners who install such cool roofs.","options":["Sentence 2","Sentence 4","Sentence 5","Sentence 3"],"answer":3,"explanation":"The paragraph is about urban heat: cause (1), effect (2), remedy (4, 'this incoming energy') and policy (5, 'such cool roofs'). Sentence 3 is about another climate threat to cities; its 'meanwhile' makes it look connected, but it breaks the cause–effect–remedy chain. Sentence 5 might look like a detour, but 'such cool roofs' ties it to sentence 4.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-135","question":"Grammar. Which of the following sentences is grammatically correct?","options":["One of the managers who were promoted last year has resigned.","One of the managers who was promoted last year have resigned.","One of the managers who were promoted last year have resigned.","One of the managers who was promoted last year has resigned."],"answer":0,"explanation":"Two verbs, two subjects. 'who' refers to 'managers' (several were promoted, and one of that group resigned), so the relative clause takes 'were'. The main subject is 'One', so the main verb is 'has resigned'. The option with 'who was … has' is the common slip: it makes 'who' refer to 'one', which changes the meaning to 'the one manager who was promoted'.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-136","question":"Grammar. Which sentence is free of a modifier error?","options":["Having reviewed the code twice, the bug still escaped the team.","Having reviewed the code twice, the team still missed the bug.","After reviewing the code twice, the bug was still missed by the team.","To review the code properly, a checklist is needed by the team."],"answer":1,"explanation":"An opening participle or infinitive phrase must describe the subject that follows it. Only 'the team' can review code. In the other options the subject is 'the bug' (twice) or 'a checklist', so the bug or the checklist is said to have reviewed the code — dangling modifiers. The passive 'was still missed by the team' does not rescue the sentence, because the grammatical subject is still 'the bug'.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-137","question":"Grammar. Fill in the blank. If the server had been patched last week, we ___ with this breach now.","options":["would not have dealt","will not be dealing","would not be dealing","had not been dealing"],"answer":2,"explanation":"This is a mixed conditional: a past condition ('had been patched last week') with a present result ('now'). The result clause therefore uses would + present (continuous) form: 'would not be dealing'. 'Would not have dealt' is the past-result form, which clashes with 'now'; 'will' belongs to real future conditions; 'had not been dealing' is not a result form at all.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-138","question":"Grammar. Find the part of the sentence that has an error. If there is none, choose \"No error\".\nThe data from both surveys suggest / that neither the price nor the features / was the main reason customers / switched to the rival product.","options":["The data from both surveys suggest","that neither the price nor the features","No error","was the main reason customers"],"answer":3,"explanation":"With 'neither … nor', the verb agrees with the nearer subject, 'the features', so it should be 'were the main reason'. 'The data … suggest' is correct (data is treated as plural in formal usage) and is the tempting distractor; 'the price nor the features' is correctly paired.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-139","question":"Grammar. Which of the following sentences is correct?","options":["The battery life of the new phone is longer than that of the old phone.","The battery life of the new phone is longer than the old phone.","The new phone's battery life is longer than the old phone.","The battery life of the new phone is longer than those of the old phone."],"answer":0,"explanation":"A comparison must set like against like: battery life against battery life. 'That of the old phone' stands for 'the battery life of the old phone'. The first two compare a battery life with a phone; 'those' is plural and cannot stand for the singular 'battery life'.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
  {"id":"apt-verbal-placement-140","question":"Grammar. How many of the following sentences are grammatically correct?\n(i) The manager asked Riya and me to present the findings.\n(ii) It was they who approved the budget.\n(iii) Let's keep this matter strictly between you and I.\n(iv) The award will go to whoever finishes the course first.","options":["1","3","2","4"],"answer":1,"explanation":"(i) is correct: 'me' is an object of 'asked' (test: 'asked me'). (ii) is correct in formal usage: after 'It was', the pronoun takes the subject form 'they'. (iii) is wrong: 'between' is a preposition and needs the object form 'you and me'. (iv) is correct even though 'whoever' follows 'to': the pronoun's case is decided inside its own clause, where it is the subject of 'finishes'. So three are correct; '2' is the answer of anyone who 'corrects' (iv) to 'whomever'.","difficulty":"very-hard","source":"Product company OA · CAT VARC level"},
];

export default questions;
